import fs from 'node:fs/promises';
import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
import {loadCriterionCorrespondences,matchCriteria} from '../../../src/eval/restaurant/agent-loop/criterion-correspondence.ts';
const dir='.eval-artifacts/checkpoint-c-live-20261020/c18-offline-reassessment-20261022';
const sha=b=>createHash('sha256').update(b).digest('hex');
// Independent literal SHA roster from the original C18, not generated by the loader.
const expected={
 'c-02':['18438d5e7d8a715633bcd1ceed4eb6871730fc2d8cd9e3c5da3d52641f041fa7',[[0,1],[2,3]]],
 'c-05':['cbf077d27fcc65d99ae5586019e155961e96211f35b13724b3ee4ae31f7c807c',[[0,0]]],
 'c-06':['dc55446db4493821154906b98b7e7b267bbf15a78f0f292abc1a82f46f12f154',[[0,0]]],
 'c-09':['6979f02338005e04b095450abcc2af12551ecb549d0c780406e965b4c5ddffe9',[[0,0]]],
 'c-10':['eee39f1823a4c453ab49977acd2bf7359338564d47e0dabc5e50496331ceac1b',[[0,0]]],
 'c-12':['842f6eeeed682a7b86ce2f866b2a6e33d7c730e71dbc589d436c97ccdfb28b96',[[0,1],[2,3]]],
 'c-13':['55937c71755753a6a8953debaf4d82688a56755adaf303c0a33ec501ec25f58c',[[0,0]]],
 'c-14':['f694c05c00be46aa315329822c65701b8656506f035f5799b2423d5c55adbde7',[[0,0]]],
 'c-16':['3c3184418a55f485471949f27a293e4d9faad3c693ee56747c93f25c475a009a',[[0,1],[2,3]]],
};
const old=JSON.parse(await fs.readFile(`${dir}/correspondence-before.json`));
const index=JSON.parse(await fs.readFile(`${dir}/c18-inputs.json`));
assert.equal(index.review.sha256,'de649548e120947f4dd3e5b347dd0c2b030a201ea8371ace4fc070cb978fdff0');
assert.equal(sha(await fs.readFile(index.review.path)),index.review.sha256);
const registry=loadCriterionCorrespondences();
assert.deepEqual(registry.entries.slice(0,old.entries.length),old.entries);
const added=registry.entries.slice(old.entries.length);assert.equal(added.length,9);
let n=0;
for(const e of added){
 const [expectedSha,pairs]=expected[e.runId];assert.equal(e.artifactSha256,expectedSha);
 assert.deepEqual(e.pairs.map(p=>[p.goldIndex,p.actualIndex]),pairs);
 const input=index.runs.find(r=>r.runId===e.runId),bytes=await fs.readFile(input.artifactPath);assert.equal(sha(bytes),expectedSha);
 const a=JSON.parse(bytes),gold=a.materializedCase.semantic.criteria,actual=a.finalSnapshot.domainState.intentDraft.criteria;
 const matched=matchCriteria(gold,actual,e.pairs);
 for(const p of e.pairs){
  assert.equal(gold[p.goldIndex].polarity,actual[p.actualIndex].polarity);assert.equal(gold[p.goldIndex].strength,actual[p.actualIndex].strength);
  assert.equal(p.goldTextSha256,sha(gold[p.goldIndex].value));assert.equal(p.actualTextSha256,sha(actual[p.actualIndex].text));
  assert.ok(p.refs.some(r=>r.includes(index.review.path)&&r.includes(index.review.sha256)));
  assert.ok(matched.some(m=>m.goldIndex===p.goldIndex&&m.actualIndex===p.actualIndex&&m.method==='REVIEWED_SEMANTIC_INDEX'));n++;
 }
 if(pairs.length===2)assert.ok(!matched.some(m=>m.goldIndex===0&&m.actualIndex===3||m.goldIndex===2&&m.actualIndex===1));
}
assert.equal(n,12);assert.ok(!registry.entries.some(e=>e.artifactSha256==='0'.repeat(64)));
console.log(JSON.stringify({status:'PASS',literalApprovedArtifactSHAs:9,reviewedPairs:12,historicalEntriesUnchanged:13,crossPairsMatched:0,models:0,websites:0}));
